      "card_ids": ["C03", "C06", "C07", "C13", "C11", "C19", "C23", "C24"]
    },
    {
      "claim": "Stavudine and zidovudine nucleoside analogs had oral bioavailability of 61-78% and 61%, respectively, supporting adequate absorption for this compound class.",
      "card_ids": ["C08", "C05"]
    },
    {
      "claim": "New rufinamide and salicin L2 records concern different scaffolds and conditions (food effects, dose-dependent decreases, species comparisons) and are not transferable to the query; none provides affirmative F < 20% evidence.",
      "card_ids": ["C20", "C22", "C26", "C27", "C21", "C25"]
    }
